#!/usr/bin/env python3 -I
"""Golden fixtures for the fine-tuned live notes mode (live_summary/finetuned.rs), generated by the
training-side Python in ~/Developer/minutes-distill, which is the source of truth.

usage: python3 -I gen_fixtures.py [MEETING] [WINDOWS]
       (the chat-template fixture needs the training venv: train/.venv/bin/python -I; CPU only, tokenizer only)

Writes, next to this file:
  replay.json    MEETING's first WINDOWS windows replayed with the gold labels and the simulated user's
                 events, as render_training.render_run does: each window's user prompt, its gold compact ops,
                 and the notes after it (Living.render)
  compact.json   compact_ops.decode cases (parsed ops or the error)
  living.json    Living sequences: events, ops (with the closed loop's repair and the validator's duplicate
                 checks) and the reasons / notes after each step
  pause.json     simulate_scheduler.py --mode pause over the start of MEETING's canonical transcript
  template.json  the HF chat template (gemma-4-E2B-it) for one window's system + user turns
AMI corpus text is CC BY 4.0; only short excerpts are kept.
"""
import json, os, sys

HOME = os.path.expanduser("~/Developer/minutes-distill")
sys.path.insert(0, f"{HOME}/scripts")
import compact_ops  # noqa: E402
import render_training as RT  # noqa: E402
import simulate_scheduler as SS  # noqa: E402
from validate_labels import Living, load_events, dup_checks  # noqa: E402

OUT = os.path.dirname(os.path.abspath(__file__))
MEETING = sys.argv[1] if len(sys.argv) > 1 else "ES2002a"
N = int(sys.argv[2]) if len(sys.argv) > 2 else 24
STAGE = f"{HOME}/data/stage2"
REPAIRABLE = {"too_many_children", "parent_unknown", "nested_child", "parent_in_closed_topic"}


def dump(name, obj):
    with open(os.path.join(OUT, name), "w") as f:
        json.dump(obj, f, ensure_ascii=False, indent=1)
        f.write("\n")


def replay():
    windows = [json.loads(l) for l in open(f"{STAGE}/{MEETING}.w30.windows.jsonl") if l.strip()][:N]
    labels = RT.load_labels(f"{STAGE}/{MEETING}.w30.u1.labels.jsonl")
    events = load_events(f"{STAGE}/{MEETING}.w30.u1.events.jsonl")
    RT.renumber(labels, events)
    living, topic, since, closed, out = Living(), None, None, [], []
    for w in windows:
        i = w["window_index"]
        evs = events.get(i, [])
        for ev in evs:
            living.apply_event(ev)
        lab = labels[i]
        user = RT.render_user(w, living, topic, since, closed[-4:])
        ops = compact_ops.encode(lab)
        assert compact_ops.decode(ops, living.maxid + 1)["ops"] == lab["ops"], i  # sequential and encodable
        td = lab.get("topic_decision") or {}
        if td.get("same") is False and td.get("topic"):
            closed.extend(living.notes[j]["text"] for j in living.order if j in living.cur and not living.notes[j]["dropped"])
            living.new_topic(); living.topic = topic = td["topic"]; since = w["start"]
        elif topic is None and td.get("topic"):
            living.topic = topic = td["topic"]; since = w["start"]
        reasons = [living.apply(op, None)[0] for op in lab.get("ops") or []]
        out.append({"window": {k: w[k] for k in ("window_index", "start_ms", "end_ms", "start", "end", "max_entries",
                                                 "segments", "context_segments", "transcript", "context")},
                    "events": [{k: v for k, v in e.items() if k != "src"} for e in evs],
                    "user": user, "ops": ops, "reasons": reasons, "notes_after": living.render()})
    dump("replay.json", {"meeting": MEETING, "system_prompt": RT.SYSTEM_PROMPT, "windows": out})


COMPACT = [
    "", ".", "  .\n", "T=Remote control design", "T=Budget\n+p 01:05|Price set at 25 euros per unit",
    "+p 02:53-03:17|~€25 price | mid-range; 25–35-year-olds",
    "+a 03:30-03:31 Industrial designer|write spec",
    "+a 03:30|ask about it", "+d 04:00|Battery: rechargeable; dock included\n>7 p 04:10|Dock sold separately",
    ">u2 p 03:01-03:05|y", ">7 a 03:01 Craig|send the drawings",
    "~7|z", "~7 k=d @04:00 o=Craig|z2", "~u1|edited user note", "~7 k=p|back to a point", "-3", "-u2",
    "+p 01:00|a\n+p 01:05|b\n>8 p 01:06|c\n~2|d\n-1",
    "hello", "+x 01:00|t", "+p 1:00|t", "~|t", "+p 01:00 oops", "+p 01:00 Craig|owner on a point",
    "+p 01:00|a\nT=late topic", "T=", "T=   ", "+p 100:00-101:30|long meeting", "- 3", "-3 ", "+p 01:00|",
    ". \n+p 01:00|x", "T=Topic\n.", "+p 01:00|text with | a pipe", "~7 o=Product manager|own it",
]


def compact():
    cases = []
    for t in COMPACT:
        for nid in (5,):
            try:
                cases.append({"text": t, "next_id": nid, "decoded": compact_ops.decode(t, nid)})
            except compact_ops.OpsError as e:
                cases.append({"text": t, "next_id": nid, "error": str(e)})
    dump("compact.json", cases)


def run_steps(steps):
    """Each step: {"event": ev} | {"topic": title} | {"output": compact, "window": [start_ms, end_ms]} where output is applied like
    the closed loop (decode at NEXT ID; a child rejected only for a repairable reason becomes an add) plus the runtime's
    duplicate filter (validate_labels.dup_checks, judged before the op is applied)."""
    living, out = Living(), []
    for st in steps:
        rec = dict(st)
        if "event" in st:
            rec["changed"] = living.apply_event(st["event"])
        elif "topic" in st:
            living.new_topic(); living.topic = st["topic"]
        else:
            lab = compact_ops.decode(st["output"], living.maxid + 1)
            results = []
            for op in lab["ops"]:
                r = {"op": op}
                dup = pre_dup(op, living)
                if dup:
                    r["duplicate"] = dup; results.append(r); continue
                reasons, _ = living.apply(op, None)
                if reasons and op["op"] == "child" and all(x.split(":")[0] in REPAIRABLE for x in reasons):
                    r["repaired_from"] = reasons
                    op = {k: v for k, v in op.items() if k != "parent"} | {"op": "add"}
                    dup = pre_dup(op, living)
                    if dup:
                        r["duplicate"] = dup; results.append(r); continue
                    reasons, _ = living.apply(op, None)
                r["reasons"] = reasons
                results.append(r)
            rec["results"] = results
        rec["maxid"] = living.maxid
        rec["notes"] = living.render()
        out.append(rec)
    return out


def pre_dup(op, living):
    """dup_checks as the runtime runs it: before the op is applied (the validator runs it after, skipping the op's own
    note, so the result is the same), an edit judged with its target's current text as the old text."""
    if op["op"] not in ("add", "child", "edit"):
        return []
    merged = None
    if op["op"] == "edit":
        t = living.notes.get(op["id"])
        if t is None:
            return []
        merged = {"_old_text": t["text"]}
    return dup_checks(op, living, merged)


def ev_add(uid, ms, text):
    return {"type": "user_add", "id": uid, "ms": ms, "t": f"{ms // 60000:02d}:{ms // 1000 % 60:02d}", "text": text}


