def living_cases():
    dump("living.json", {name: run_steps(steps) for name, steps in LIVING.items()})


def pause():
    doc, you, words, segs = SS.load_segments(f"{HOME}/canonical/{MEETING}.json")
    segs = [s for s in segs if s["start_ms"] < 6 * 60_000]
    tmp = os.path.join(OUT, ".pause.tmp.jsonl")
    import io, contextlib
    orig = SS.load_segments
    SS.load_segments = lambda _p: (doc, you, words, list(segs))
    try:
        with contextlib.redirect_stdout(io.StringIO()):
            SS.main_pause("unused", tmp, 20.0, 45.0, 0.8, 12, 20.0)
    finally:
        SS.load_segments = orig
    windows = [json.loads(l) for l in open(tmp) if l.strip()]
    os.remove(tmp)
    ordered = sorted(segs, key=lambda s: (s["start_ms"], s["end_ms"]))
    dump("pause.json", {"meeting": MEETING,
                        "segments": [{"start_ms": s["start_ms"], "end_ms": s["end_ms"], "speaker": s["speaker"], "text": s["text"]}
                                     for s in ordered],
                        "windows": [{k: w[k] for k in ("start_ms", "end_ms", "start", "end", "transcript", "context")} for w in windows]})


def template():
    try:
        from transformers import AutoTokenizer
    except ImportError:
        print("template.json skipped (run with the training venv)")
        return
    tok = AutoTokenizer.from_pretrained(f"{HOME}/train/models/gemma-4-E2B-it")
    rep = json.load(open(os.path.join(OUT, "replay.json")))
    user = rep["windows"][3]["user"] + "\n"  # a trailing newline: the template trims it
    msgs = [{"role": "system", "content": RT.SYSTEM_PROMPT}, {"role": "user", "content": user}]
    dump("template.json", {"system": RT.SYSTEM_PROMPT, "user": user,
                           "rendered": tok.apply_chat_template(msgs, add_generation_prompt=True, tokenize=False),
                           "dot_token_ids": tok.encode(".", add_special_tokens=False)})


if __name__ == "__main__":
    replay(); compact(); living_cases(); pause(); template()
